package com.yeyamo_mobile.api.content_service.interfaces.rest;
import java.time.Instant;import java.util.*;import com.yeyamo_mobile.api.content_service.domain.model.*;
public record PostResponse(UUID id,String authorId,String caption,PostStatus status,PostVisibility visibility,UUID catalogAssetId,PostReferenceType referenceType,String referenceId,List<UUID> mediaIds,Set<String> hashtags,
 String countryCode,UUID adminLevel1Id,UUID adminLevel2Id,UUID cityId,UUID localityId,Double latitude,Double longitude,String languageCode,Instant createdAt,Instant updatedAt,Instant publishedAt,Instant archivedAt,long version){
 public static PostResponse from(Post p){return new PostResponse(p.getId(),p.getAuthorId(),p.getCaption(),p.getStatus(),p.getVisibility(),p.getCatalogAssetId(),p.getReferenceType(),p.getReferenceId(),p.getMediaIds(),p.getHashtags(),
  p.getGeography()==null?null:p.getGeography().getCountryCode(),p.getGeography()==null?null:p.getGeography().getAdminLevel1Id(),p.getGeography()==null?null:p.getGeography().getAdminLevel2Id(),p.getGeography()==null?null:p.getGeography().getCityId(),p.getGeography()==null?null:p.getGeography().getLocalityId(),p.getGeography()==null?null:p.getGeography().getLatitude(),p.getGeography()==null?null:p.getGeography().getLongitude(),p.getGeography()==null?null:p.getGeography().getLanguageCode(),p.getCreatedAt(),p.getUpdatedAt(),p.getPublishedAt(),p.getArchivedAt(),p.getVersion());}
}
